    async def passthrough(
        self,
        id: str,
        body: Mapping[str, Any],
        *,
        idempotency_key: str | None = None,
        timeout: float | None = None,
        total_timeout: float | None = None,
        max_retries: int | None = None,
        server_timeout: int | None = None,
    ) -> dict[str, Any]:
        """Send a raw qbXML request.

        Sends qbXML request elements directly to the end user's QuickBooks Desktop and returns QuickBooks' response. Send JSON (`application/json`) or a `<QBXMLMsgsRq>` fragment (`application/xml`); the response uses the same format. We add the qbXML envelope, `onError="stopOnError"` unless you set it, and a `newMessageSetID` for writes. A body that contains any element other than a query (`...QueryRq`) is a write: send an `Idempotency-Key` to make retries safe. A read-only secret key can send only queries; a write returns `403 API_KEY_READ_ONLY`. The response is `200` with each message's own status; the call fails only when QuickBooks processed no message successfully. Each call creates a request resource (`Daapi-Request-Id`).

        Operation ``endUsers.passthrough``: ``POST /v1/end-users/{id}/passthrough/{integrationSlug}``.

        Args:
            id: Unique identifier for the end user.
            body: qbXML request elements as JSON, keyed by element name (for example ``{"CustomerQueryRq": {"MaxReturned": 5}}``).
            idempotency_key: Makes the write safe to retry (``Idempotency-Key``). Defaults to a new UUID that is reused on every retry of this call.
            timeout: Client-side timeout in seconds for each HTTP attempt; also the time budget for waiting on a request that is still running in QuickBooks. Defaults to the client's ``timeout``.
            total_timeout: Time budget in seconds for the whole call: every attempt, retry backoff and the wait for a pending request. Defaults to the client's ``total_timeout`` (none).
            max_retries: Retries for network errors, 429 and retryable 5xx responses. Defaults to the client's ``max_retries``.
            server_timeout: Seconds the API waits for QuickBooks before answering (``Daapi-Timeout-Seconds``, 1-300). Defaults to the client's ``server_timeout`` or the API default.

        Returns:
            The qbXML response elements as JSON.
        """
        return await self._client._request(
            _END_USERS_PASSTHROUGH,
            "POST",
            "/v1/end-users/" + _pp("id", id) + "/passthrough/quickbooks_desktop",
            cast_to=_as_dict,
            body=body,
            idempotency_key=idempotency_key,
            timeout=timeout,
            total_timeout=total_timeout,
            max_retries=max_retries,
            server_timeout=server_timeout,
        )

