    async def reset_company_file(
        self,
        id: str,
        *,
        mode: EndUserResetCompanyFileInputMode,
        confirm: Literal["reset_company_file"],
        idempotency_key: str | None = None,
        timeout: float | None = None,
        total_timeout: float | None = None,
        max_retries: int | None = None,
    ) -> EndUser:
        """Reset the company file.

        Re-binds the connection after the company file was moved or renamed (`mode: path`) or the company itself was renamed (`mode: identity`), which otherwise leaves the connection in `company_file_mismatch` or `QBD_COMPANY_FILE_NOT_FOUND`. Ask the end user to open the correct company file in QuickBooks first. The connection checks the file at the next Web Connector check-in. Queued requests stay queued.

        Operation ``endUsers.resetCompanyFile``: ``POST /v1/end-users/{id}/reset-company-file``.

        Args:
            id: Unique identifier for the end user.
            mode: `path`: forget the stored company file location (the file was moved or renamed on disk); the next session uses the file open in QuickBooks. `identity`: also forget the company identity (the company was renamed, or the end user deliberately switched to another file); the next session that QuickBooks answers becomes the connected company file. Unknown values are passed through as strings.
            confirm: Must be `reset_company_file`. Confirms you checked with the end user which company file is correct: with `identity`, whatever file is open next is accepted.
            idempotency_key: Makes the write safe to retry (``Idempotency-Key``). Defaults to a new UUID that is reused on every retry of this call.
            timeout: Client-side timeout in seconds for each HTTP attempt; also the time budget for waiting on a request that is still running in QuickBooks. Defaults to the client's ``timeout``.
            total_timeout: Time budget in seconds for the whole call: every attempt, retry backoff and the wait for a pending request. Defaults to the client's ``total_timeout`` (none).
            max_retries: Retries for network errors, 429 and retryable 5xx responses. Defaults to the client's ``max_retries``.

        Returns:
            The EndUser object.
        """
        return await self._client._request(
            _END_USERS_RESET_COMPANY_FILE,
            "POST",
            "/v1/end-users/" + _pp("id", id) + "/reset-company-file",
            cast_to=EndUser.from_wire,
            body={
                "mode": mode,
                "confirm": confirm,
            },
            idempotency_key=idempotency_key,
            timeout=timeout,
            total_timeout=total_timeout,
            max_retries=max_retries,
        )

